import React from "react";
import { auth, signIn, signOut } from "../auth";
import { Plane, Calendar, Tag, ArrowRight, User } from "lucide-react";

async function getDeals() {
  try {
    const res = await fetch('http://localhost:8000/api/deals', { cache: 'no-store' });
    if (!res.ok) return { deals: [] };
    return res.json();
  } catch (error) {
    return { deals: [] };
  }
}

export default async function Home() {
  const session = await auth();
  const data = await getDeals();
  const deals = data.deals || [];

  return (
    <main className="min-h-screen bg-slate-50 font-sans text-slate-900">
      {/* Navigation */}
      <nav className="sticky top-0 z-50 w-full bg-white/80 backdrop-blur-md shadow-sm border-b border-slate-200">
        <div className="max-w-7xl mx-auto px-6 py-4 flex justify-between items-center">
          <div className="flex items-center gap-2">
            <Plane className="h-8 w-8 text-blue-600" />
            <h1 className="text-2xl font-black tracking-tighter text-slate-900">think a trip<span className="text-blue-600">.</span></h1>
          </div>
          
          <div>
            {session ? (
              <div className="flex items-center gap-4">
                <div className="flex items-center gap-2 bg-slate-100 px-4 py-2 rounded-full border border-slate-200">
                  <User className="h-4 w-4 text-slate-500" />
                  <span className="text-sm font-semibold text-slate-700">VIP Member</span>
                </div>
                <form action={async () => { "use server"; await signOut(); }}>
                  <button className="text-sm font-bold text-slate-500 hover:text-slate-900 transition-colors">
                    Sign Out
                  </button>
                </form>
              </div>
            ) : (
               <form action={async () => { "use server"; await signIn(); }}>
                  <button className="bg-slate-900 hover:bg-slate-800 text-white px-6 py-2.5 rounded-full text-sm font-bold transition-all shadow-md">
                    Member Login
                  </button>
               </form>
            )}
          </div>
        </div>
      </nav>

      {/* Hero Section */}
      <div className="relative bg-slate-900 overflow-hidden">
        <div className="absolute inset-0 bg-gradient-to-br from-slate-900 via-blue-900 to-slate-900 opacity-90"></div>
        <div className="relative max-w-7xl mx-auto px-6 py-24 lg:py-32 flex flex-col items-center text-center">
          <span className="bg-blue-500/20 text-blue-300 border border-blue-500/30 px-4 py-1.5 rounded-full text-xs font-bold tracking-widest uppercase mb-6">
            Live Global Database
          </span>
          <h2 className="text-5xl lg:text-7xl font-extrabold text-white tracking-tight mb-6 max-w-4xl">
            We find the mistakes. <br/> <span className="text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-emerald-400">You fly for pennies.</span>
          </h2>
          <p className="text-lg lg:text-xl text-slate-300 max-w-2xl font-medium mb-10">
            Exclusive error fares and heavily discounted outbound flight deals from major Indian hubs to over 85 global destinations.
          </p>
          {!session && (
            <form action={async () => { "use server"; await signIn(); }}>
               <button className="bg-blue-600 hover:bg-blue-500 text-white px-8 py-4 rounded-full text-lg font-black transition-all shadow-xl flex items-center gap-2">
                 Join Premium Deal Club <ArrowRight className="h-5 w-5" />
               </button>
            </form>
          )}
        </div>
      </div>

      {/* Main Deal Dashboard */}
      <div className="max-w-7xl mx-auto px-6 py-16">
        
        {/* Aesthetic Filter Bar */}
        <div className="flex flex-wrap items-center gap-3 mb-10 border-b border-slate-200 pb-6">
          <span className="text-sm font-bold text-slate-400 uppercase tracking-wider mr-4">Departing:</span>
          {['Anywhere', 'DEL', 'BOM', 'BLR', 'HYD', 'MAA'].map((hub, i) => (
            <button key={hub} className={`px-5 py-2 rounded-full text-sm font-bold transition-all ${i === 0 ? 'bg-slate-900 text-white shadow-md' : 'bg-white text-slate-600 border border-slate-200 hover:border-slate-400 hover:bg-slate-50'}`}>
              {hub}
            </button>
          ))}
        </div>

        {deals.length === 0 ? (
          <div className="text-center py-20 bg-white rounded-3xl border border-slate-200 shadow-sm">
            <Plane className="h-16 w-16 text-slate-300 mx-auto mb-4 animate-bounce" />
            <h3 className="text-2xl font-bold text-slate-700">Hunting for deals...</h3>
            <p className="text-slate-500 mt-2">Check back shortly. Our bots are scanning global databases.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {deals.map((deal: any, index: number) => {
              const currentPrice = parseInt(deal.price.replace(/[^0-9]/g, '')) || 45000;
              const fakeOriginal = Math.floor(currentPrice * (1.4 + Math.random() * 0.4));
              
              return (
              <div key={index} className="group flex flex-col bg-white rounded-3xl border border-slate-200 shadow-sm hover:shadow-xl transition-all overflow-hidden relative">
                
                <div className="absolute top-4 right-4 bg-emerald-500 text-white text-xs font-bold px-3 py-1 rounded-full shadow-sm z-10">
                  Save {Math.round(((fakeOriginal - currentPrice) / fakeOriginal) * 100)}%
                </div>

                <div className="p-6 pb-0 mb-4 relative">
                  <div className="flex items-center gap-2 mb-4 text-xs font-bold text-slate-400 uppercase tracking-widest">
                    <Plane className="h-4 w-4" /> {deal.airline}
                  </div>
                  <div className="flex items-center justify-between mb-2">
                     <span className="text-4xl font-black text-slate-900">{deal.origin}</span>
                     <ArrowRight className="h-6 w-6 text-slate-300" />
                     <span className="text-4xl font-black text-slate-900">{deal.destination}</span>
                  </div>
                </div>
                
                <div className="px-6 py-4 bg-slate-50 border-t border-slate-100 flex-grow flex flex-col justify-between">
                  <div className="flex items-center gap-3 text-sm text-slate-600 font-medium mb-6">
                    <Calendar className="h-4 w-4 text-slate-400" /> {deal.date || 'Flexible Dates'}
                  </div>
                  <div className="flex items-end justify-between">
                    <div>
                      <p className="text-sm text-slate-400 line-through font-medium mb-0.5">₹{fakeOriginal.toLocaleString('en-IN')}</p>
                      <p className="text-3xl font-black text-emerald-600">{deal.price}</p>
                    </div>
                    {session ? (
                      <button className="bg-slate-900 hover:bg-slate-800 text-white p-3 rounded-xl transition-colors shadow-md">
                        <ArrowRight className="h-6 w-6" />
                      </button>
                    ) : (
                      <form action={async () => { "use server"; await signIn(); }}>
                        <button className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-xl text-sm font-bold transition-colors shadow-md flex items-center gap-1">
                          Unlock <Tag className="h-3 w-3" />
                        </button>
                      </form>
                    )}
                  </div>
                </div>
              </div>
            )})}
          </div>
        )}
      </div>
      
      <footer className="bg-white border-t border-slate-200 mt-20">
        <div className="max-w-7xl mx-auto px-6 py-12 flex flex-col md:flex-row justify-between items-center gap-4 text-slate-500 font-medium">
          <p>© 2026 think a trip. All rights reserved.</p>
        </div>
      </footer>
    </main>
  );
}
